parameters.jsCode:
/**
 * Source Exclusion Filter
 * Filters out content authored or published by Syntech's own accounts.
 * Two distinct blocklists: URL-shape patterns and author-name patterns.
 * Author check exists because LinkedIn/X cross-posts often surface with a
 * third-party URL but author = 'Syntech Biofuel' — the URL filter alone misses these.
 */

const urlPatterns = [
  'syntechbiofuel.com',
  'facebook.com/syntechbiofuel',
  'x.com/syntechbiofuel',
  'twitter.com/syntechbiofuel',
  'instagram.com/syntechbiofuel',
  'linkedin.com/company/syntechbiofuel',
  'linkedin.com/posts/syntechbiofuel',
  'syntechbiofuel.medium.com',
];

// Author names as they appear on source platforms (lowercased here).
// 'syntech biofuel' has a space — match against the lowercased author field directly.
const authorPatterns = [
  'syntech biofuel',
  'syntech biofuels',
  'syntechbiofuel',
];

const filtered = [];
const excluded = [];

for (const item of $input.all()) {
  const url = (item.json.url || '').toLowerCase();
  const author = (item.json.author || '').toLowerCase();

  const urlBlocked = urlPatterns.some(p => url.includes(p));
  const authorBlocked = author && authorPatterns.some(p => author.includes(p));

  if (urlBlocked || authorBlocked) {
    excluded.push({ url: item.json.url, author: item.json.author, reason: urlBlocked ? 'url' : 'author' });
  } else {
    filtered.push(item);
  }
}

if (excluded.length > 0) {
  console.log(`Source Exclusion: filtered ${excluded.length} Syntech-authored items`, excluded);
}

return filtered;

/**
 * Pre-filter: 3-tier relevance check to reduce LLM costs
 *
 * Tier 1: "Syntech" present (case-insensitive) → instant pass
 * Tier 3: Surname + biofuel context, OR Syntech-specific term → needs LLM verification
 *
 * Items failing all tiers are filtered out.
 */

const surnames = ["bingham", "hart", "olone"];

const biofuelTerms = [
    "biofuel",
    "biofuels",
    "biodiesel",
    "bioethanol",
    "renewable fuel",
    "sustainable fuel",
    "green fuel",
    "hvo",
    "saf",
    "sustainable aviation",
    "used cooking oil",
    "uco",
    "waste oil",
    "feedstock",
    "decarbonization",
    "decarbonisation",
    "net zero",
    "net-zero",
    "carbon neutral",
];

const syntechSpecificTerms = [
    "grangemouth",
    "kingsnorth",
    "kent",
    "asb",
    "advanced sustainable biofuel",
    "circular biofuel",
];

const results = [];

for (const item of $input.all()) {
    const content = (item.json.content || "").toLowerCase();
    const title = (item.json.title || "").toLowerCase();
    const text = content + " " + title;

    const hasSyntech = /syntech/i.test(text);
    const hasSurname = surnames.some((name) => text.includes(name));
    const hasBiofuelContext = biofuelTerms.some((term) => text.includes(term));
    const hasSyntechSpecific = syntechSpecificTerms.some((term) =>
        text.includes(term),
    );

    let tier = null;
    let pass = false;

    // Tier 1: Syntech explicitly mentioned
    if (hasSyntech) {
        tier = 1;
        pass = true;
    }
    // Tier 3: Surname + biofuel context, OR Syntech-specific term
    else if ((hasSurname && hasBiofuelContext) || hasSyntechSpecific) {
        tier = 3;
        pass = true;
        item.json._needsLlmVerification = true;
    }

    if (pass) {
        item.json._preFilterTier = tier;
        results.push(item);
    }
}

console.log(
    `Pre-filter: ${results.length} items passed (Tier 1: instant, Tier 3: pending LLM)`,
);

return results;

